  [`POST ${v}/companies/{companyId}/opening-balance-requests`]: { tag: 'Ledger', summary: 'Request an opening-balance journal (ledger:opening-balance). Validated like a journal but not posted: a pending request is not a ledger entry. Posted after approval by a different person, or at once when the company policy exempts it', body: ['CreateJournalRequest', C.createJournalRequestSchema], ok: [201, 'JournalRequest', 'Request created (or posted, when exempt)'], extraErrors: [422] },
  [`POST ${v}/companies/{companyId}/control-adjustment-requests`]: { tag: 'Ledger', summary: 'Request an exceptional adjustment of a control account (ledger:control-adjustment): reason and evidence required; approval per policy', body: ['CreateJournalRequest', C.createJournalRequestSchema], ok: [201, 'JournalRequest', 'Request created (or posted, when exempt)'], extraErrors: [422] },
  [`GET ${v}/companies/{companyId}/journal-requests`]: { tag: 'Ledger', summary: 'Journal requests, newest first (filter by status and kind)', query: C.requestListQuerySchema, ok: [200, 'JournalRequestPage', 'Requests'] },
  [`GET ${v}/companies/{companyId}/journal-requests/{requestId}`]: { tag: 'Ledger', summary: 'One journal request with its policy snapshot and outcome', ok: [200, 'JournalRequest', 'Request'] },
